int select_disc(struct cdrom_device_info *cdi, unsigned long arg)
{
    if (!cdi->ops->select_disc) {
        return -EINVAL;
    }

    if (arg >= cdi->max_discs) {
        return -EINVAL;
    }

    if (cdi->ops->select_disc(cdi, arg)) {
        return -EIO;
    }

    return 0;
}

int cdrom_select_disc(struct cdrom_device_info *cdi, unsigned long arg)
{
    if (!cdi->capacity)
        return -EINVAL;

    if (arg >= cdi->capacity)
        return -EINVAL;

    if (cdi->select_disc)
        return cdi->select_disc(cdi, arg);

    return generic_select_disc(cdi, arg);
}

int cdrom_select_disc(struct cdrom_device_info *cdi, unsigned long arg)
{
    if (!cdi->capability & CDC_SELECT_DISC)
        return -ENOSYS;

    if (arg >= cdi->n_discs)
        return -EINVAL;

    if (cdi->select_disc)
        return cdi->select_disc(cdi, arg);

    return generic_select_disc(cdi, arg);
}

int select_disc(struct cdrom_device_info *cdi, unsigned long arg)
{
    if (!cdi->capability & CDC_SELECT_DISC) {
        return -EINVAL;
    }

    if (arg >= cdi->n_discs) {
        return -EINVAL;
    }

    if (cdi->ops->select_disc) {
        return cdi->ops->select_disc(cdi, arg);
    } else {
        return generic_select_disc(cdi, arg);
    }
}

int select_disc(struct cdrom_device_info *cdi, unsigned long arg)
{
    if (!cdi->ops || !cdi->ops->select_disc)
        return -EINVAL;

    if (arg >= CDROM_DISC_LIMIT)
        return -EINVAL;

    if (cdi->ops->select_disc(cdi, arg))
        return -EIO;

    return 0;
}
